import { CjsNullEventCallback } from "../../types";
import { onLoad } from "./LoadEvent";

/**
 * Extecutes when slided by touch of mouse drag down by certain threshold
 */
export function onSlideDown(f: CjsNullEventCallback, slideThreshold = 10) {
    return onLoad((cjsEvent) => {
        let startY = 0;
        let lastClientY = 0;

        const start = (event: Event) => {
            const e = event as MouseEvent | TouchEvent;
            const clientY = (!("touches" in e) ? e.clientY : e.touches[0].clientY);

            lastClientY = clientY;
            startY = clientY;
        }

        const move = (event: Event) => {
            const e = event as MouseEvent | TouchEvent
            const clientY = (!("touches" in e) ? e.clientY : e.touches[0].clientY);
            const moveProgressed = clientY + 1 >= lastClientY;
            const deltaY = clientY - startY;

            if(!moveProgressed) {
                startY = 0;
                return;
            }

            if(deltaY > slideThreshold) {
                f(cjsEvent)

                startY = 0;
            }

            lastClientY = clientY;
        }

        const { source } = cjsEvent;

        source.addEventListener('mousedown', start)
        source.addEventListener('touchstart', start)

        source.addEventListener('mousemove', move);
        source.addEventListener('touchmove', move);
    });
}